package repository;

import domain.entities.User;
import domain.exceptions.RepositoryException;
import domain.validator.Validator;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * PostgreSQL JDBC implementation of {@link Repository} for {@link User} entities.
 * User IDs are auto-generated by the database.
 */
public class UserDbRepository implements Repository<Integer, User> {
    private final Validator<Integer, User> validator;
    private final String url;
    private final String username;
    private final String password;

    /**
     * Creates a database repository for users.
     * @param validator the validator used before saving or updating users
     * @param url the JDBC connection URL
     * @param username the database username
     * @param password the database password
     */
    public UserDbRepository(Validator<Integer, User> validator, String url, String username, String password) {
        this.validator = validator;
        this.url = url;
        this.username = username;
        this.password = password;
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(url, username, password);
    }

    private RepositoryException translateSqlException(SQLException e, String context) {
        String state = e.getSQLState();
        if (state != null && state.startsWith("08")) {
            return new RepositoryException("Conexiunea la baza de date a esuat (serverul este oprit sau inaccesibil).", e);
        }
        if ("23505".equals(state)) {
            return new RepositoryException("Exista deja o inregistrare cu aceste date unice (ex. username duplicat).", e);
        }
        if ("23502".equals(state) || "23514".equals(state)) {
            return new RepositoryException("Datele nu respecta constrangerile bazei de date.", e);
        }
        return new RepositoryException("Eroare baza de date (" + context + "): " + e.getMessage(), e);
    }

    private User extractUser(ResultSet rs) throws SQLException {
        int id = rs.getInt("id");
        String firstName = rs.getString("first_name");
        String lastName = rs.getString("last_name");
        String user = rs.getString("username");
        String pass = rs.getString("password");
        return new User(id, firstName, lastName, user, pass);
    }

    /**
     * Inserts a new user into the database and assigns the auto-generated ID to the entity.
     * @param entity the user to be added
     * @return {@code Optional.empty()} if inserted successfully
     * @throws IllegalArgumentException if {@code entity} is null
     * @throws RepositoryException if a database error or constraint violation occurs
     */
    @Override
    public Optional<User> add(User entity) {
        if (entity == null) {
            throw new IllegalArgumentException("Entity cannot be null!");
        }
        validator.validate(entity);

        String sql = "INSERT INTO users (first_name, last_name, username, password) VALUES (?, ?, ?, ?)";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            ps.setString(1, entity.getName());
            ps.setString(2, entity.getSurname());
            ps.setString(3, entity.getUsername());
            ps.setString(4, entity.getPassword());
            ps.executeUpdate();

            try (ResultSet keys = ps.getGeneratedKeys()) {
                if (keys.next()) {
                    entity.setId(keys.getInt(1));
                }
            }
            return Optional.empty();
        } catch (SQLException e) {
            throw translateSqlException(e, "add user");
        }
    }

    /**
     * Saves a user (delegates to {@link #add(User)}).
     * @param entity the user to save
     * @return {@code Optional.empty()} if saved successfully
     * @throws IllegalArgumentException if {@code entity} is null
     * @throws RepositoryException if a database error occurs
     */
    @Override
    public Optional<User> save(User entity) {
        return add(entity);
    }

    /**
     * Finds a user by ID.
     * @param id the user ID
     * @return an {@code Optional} containing the user if found, or empty otherwise
     * @throws IllegalArgumentException if {@code id} is null
     * @throws RepositoryException if a database error occurs
     */
    @Override
    public Optional<User> findOne(Integer id) {
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null!");
        }
        String sql = "SELECT id, first_name, last_name, username, password FROM users WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return Optional.of(extractUser(rs));
                }
            }
            return Optional.empty();
        } catch (SQLException e) {
            throw translateSqlException(e, "findOne user");
        }
    }

    /**
     * Retrieves all users from the database.
     * @return an {@code Iterable} of all users
     * @throws RepositoryException if a database error occurs
     */
    @Override
    public Iterable<User> findAll() {
        List<User> users = new ArrayList<>();
        String sql = "SELECT id, first_name, last_name, username, password FROM users ORDER BY id";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {

            while (rs.next()) {
                users.add(extractUser(rs));
            }
            return users;
        } catch (SQLException e) {
            throw translateSqlException(e, "findAll users");
        }
    }

    /**
     * Deletes a user by ID.
     * @param id the ID of the user to delete
     * @return an {@code Optional} containing the deleted user, or empty if no user had that ID
     * @throws IllegalArgumentException if {@code id} is null
     * @throws RepositoryException if a database error occurs
     */
    @Override
    public Optional<User> delete(Integer id) {
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null!");
        }
        Optional<User> existing = findOne(id);
        if (existing.isEmpty()) {
            return Optional.empty();
        }

        String sql = "DELETE FROM users WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setInt(1, id);
            ps.executeUpdate();
            return existing;
        } catch (SQLException e) {
            throw translateSqlException(e, "delete user");
        }
    }

    /**
     * Updates an existing user in the database.
     * @param entity the user with updated fields
     * @return {@code Optional.empty()} if updated, or {@code Optional.of(entity)} if the ID does not exist
     * @throws IllegalArgumentException if {@code entity} or its ID is null
     * @throws RepositoryException if a database error occurs
     */
    @Override
    public Optional<User> update(User entity) {
        if (entity == null || entity.getId() == null) {
            throw new IllegalArgumentException("Entity and ID cannot be null!");
        }
        validator.validate(entity);

        String sql = "UPDATE users SET first_name = ?, last_name = ?, username = ?, password = ? WHERE id = ?";
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, entity.getName());
            ps.setString(2, entity.getSurname());
            ps.setString(3, entity.getUsername());
            ps.setString(4, entity.getPassword());
            ps.setInt(5, entity.getId());

            int affected = ps.executeUpdate();
            return affected == 0 ? Optional.of(entity) : Optional.empty();
        } catch (SQLException e) {
            throw translateSqlException(e, "update user");
        }
    }
}